{
  "schemaVersion": "0.2",
  "slug": "selectable-list-item",
  "name": "SelectableListItem",
  "status": "experimental",
  "purpose": "Selectable queue/list row with optional leading, meta, and inline actions.",
  "scenarios": [
    "Task queue row with selected highlight, status meta, and download/delete actions."
  ],
  "props": {
    "selected": {
      "type": "boolean",
      "required": false,
      "description": "Whether the row is selected."
    },
    "disabled": {
      "type": "boolean",
      "required": false,
      "description": "Disables selection."
    },
    "onSelect": {
      "type": "event",
      "required": false,
      "description": "Called when the row is activated (click / Enter / Space).",
      "payload": "() => void"
    },
    "leading": {
      "type": "node",
      "required": false,
      "description": "Optional leading media or icon. Vue slot: leading."
    },
    "meta": {
      "type": "node",
      "required": false,
      "description": "Secondary meta (status badge, caption). Vue slot: meta."
    },
    "actions": {
      "type": "node",
      "required": false,
      "description": "Inline action controls; clicks do not re-fire onSelect. Vue slot: actions."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Idle unselected row."
    },
    {
      "name": "selected",
      "description": "Selected / active row."
    },
    {
      "name": "disabled",
      "description": "Selection disabled."
    }
  ],
  "composition": {
    "allowedParents": [
      "scroll-pane",
      "workspace-split",
      "stack",
      "card",
      "page"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not nest interactive controls that need row selection inside actions without stopPropagation — actions already stop propagation."
  ],
  "a11y": {
    "role": "option",
    "keyboard": [
      "Enter",
      "Space"
    ],
    "focus": "Row is focusable when enabled.",
    "labeling": "Children provide the accessible name; aria-selected reflects selection.",
    "wcag": [
      "2.1.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Fluid row.",
    "breakpoints": {
      "compact": "Default.",
      "medium": "Default.",
      "large": "Default."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "selectable-list-item",
    "states": [
      "default",
      "selected",
      "disabled"
    ],
    "intents": [
      "select-single"
    ]
  }
}

import type { KeyboardEvent, MouseEvent, ReactNode } from 'react'
import './styles.css'

export interface SelectableListItemProps {
  selected?: boolean
  disabled?: boolean
  onSelect?: () => void
  leading?: ReactNode
  meta?: ReactNode
  actions?: ReactNode
  children?: ReactNode
  className?: string
}

export function SelectableListItem({
  selected = false,
  disabled = false,
  onSelect,
  leading,
  meta,
  actions,
  children,
  className,
}: SelectableListItemProps) {
  const classes = ['cu-selectable-list-item', className].filter(Boolean).join(' ')

  const activate = () => {
    if (disabled) return
    onSelect?.()
  }

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      activate()
    }
  }

  const onActionsClick = (event: MouseEvent<HTMLDivElement>) => {
    event.stopPropagation()
  }

  return (
    <div
      className={classes}
      role="option"
      tabIndex={disabled ? -1 : 0}
      aria-selected={selected}
      aria-disabled={disabled || undefined}
      data-selected={selected ? 'true' : 'false'}
      data-disabled={disabled ? 'true' : 'false'}
      data-ai-role="selectable-list-item"
      data-ai-intent="select-single"
      data-ai-state={disabled ? 'disabled' : selected ? 'selected' : 'default'}
      onClick={activate}
      onKeyDown={onKeyDown}
    >
      <div className="cu-selectable-list-item__row">
        {leading ? <div className="cu-selectable-list-item__leading">{leading}</div> : null}
        <div className="cu-selectable-list-item__body">
          {children}
          {meta ? <div className="cu-selectable-list-item__meta">{meta}</div> : null}
        </div>
      </div>
      {actions ? (
        <div className="cu-selectable-list-item__actions" onClick={onActionsClick}>
          {actions}
        </div>
      ) : null}
    </div>
  )
}

.cu-selectable-list-item {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: var(--cu-space-2);
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border: var(--cu-border-width-default, 1px) solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-elevated, var(--cu-color-background-default));
  color: var(--cu-color-fg-default);
  text-align: start;
  cursor: pointer;
}

.cu-selectable-list-item[data-selected='true'] {
  border-color: var(--cu-color-palette-brand);
  box-shadow: inset 0 0 0 var(--cu-border-width-hairline, 1px) var(--cu-color-palette-brand);
  background: color-mix(
    in srgb,
    var(--cu-color-palette-brand) 8%,
    var(--cu-color-background-elevated, var(--cu-color-background-default))
  );
}

.cu-selectable-list-item[data-disabled='true'] {
  opacity: 0.56;
  cursor: not-allowed;
}

.cu-selectable-list-item:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 2px;
}

.cu-selectable-list-item__row {
  display: flex;
  align-items: flex-start;
  gap: var(--cu-space-2);
  min-inline-size: 0;
}

.cu-selectable-list-item__leading {
  flex: none;
  display: inline-flex;
  align-items: center;
}

.cu-selectable-list-item__body {
  flex: 1 1 auto;
  min-inline-size: 0;
  display: flex;
  flex-direction: column;
  gap: var(--cu-space-1);
}

.cu-selectable-list-item__meta {
  color: var(--cu-color-fg-muted, color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent));
  font-size: var(--cu-typography-size-caption, 0.8125rem);
}

.cu-selectable-list-item__actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--cu-space-1);
}
